def apply_recognition_ui66(destination: Path) -> None:
    """Apply the verified additive UI66 layer to the exact cumulative UI65 runtime."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest = json.loads(manifest_file.read_text())
    parent_file = destination / 'UI_PATCH.json'
    if (manifest.get('format') != 'aj-release-files-1' or manifest.get('version') != '1.34.19'
            or manifest.get('variant') != UI_PATCH_ID):
        raise ValueError('Workspace UI66 requires the exact cumulative UI65 runtime.')
    if not parent_file.is_file() or hashlib.sha256(parent_file.read_bytes()).hexdigest() != '930859b0aea69975211b68509a669044378cb1db81afcf8bd4fb9bf1bfd62bce':
        raise ValueError('Workspace UI66 parent provenance mismatch.')
    parent = json.loads(parent_file.read_text())
    if parent.get('format') != 'wavelink-source-overlay-1' or parent.get('patch_id') != UI_PATCH_ID:
        raise ValueError('Workspace UI66 requires the reviewed UI65 parent overlay.')
    prepared = {}
    for name, record in _UI66_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New UI66 resource unexpectedly exists: ' + name)
        elif manifest['files'].get(name) != expected or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Workspace UI66 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(base64.b64decode(record['zlib_base64'], validate=True), record['bytes'] + 1)
        if (not decompressor.eof or decompressor.unused_data or len(content) != record['bytes']
                or hashlib.sha256(content).hexdigest() != record['after_sha256']):
            raise ValueError('Workspace UI66 payload integrity failure: ' + name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI66_FILES[name]['after_sha256']
    inherited = list(parent.get('includes') or [])
    if UI_PATCH_ID not in inherited:
        inherited.append(UI_PATCH_ID)
    provenance = {
        'format': 'wavelink-source-overlay-1',
        'patch_id': UI66_PATCH_ID,
        'parent_patch_id': UI_PATCH_ID,
        'parent_overlay_sha256': '930859b0aea69975211b68509a669044378cb1db81afcf8bd4fb9bf1bfd62bce',
        'upstream_version': '1.34.19',
        'upstream_archive_sha256': SOURCE_SHA256,
        'includes': inherited,
        'scope': 'Company-scoped member profiles; permission-aware Team accomplishments; reversible likes; duplicate-safe contribution ledger; frozen 1/3/5 source values; cumulative tiers and three selectable original badge families per tier; Task, maintenance, checklist, handover, Toolbox Talk and standalone stock-verification adapters.',
        'data_changes': 'Additive recognition schema v1 with an activation boundary, profiles, source events, awards, immutable ledger, reactions, idempotent operations, durable outbox and repair cursors. Existing UI65 identities, invitation roles, permissions and operational records are preserved. Existing history is not retroactively scored. Keep UI66+ after this schema opens.',
        'source_parent_extractor_sha256': 'de8c364f9395fb9ef9ef96d5bff70b5a52670a8d1044404ad85f11a287a3a2c5',
        'source_parent_variant': UI_PATCH_ID,
        'mail_startup_m01': 'Preserved by the unchanged deploy/company_entrypoint.py repository launcher; not embedded in the runtime overlay.',
        'changed_files': {name: {key: val for key, val in record.items() if key != 'zlib_base64'} for name, record in _UI66_FILES.items()},
    }
    content = (json.dumps(provenance, indent=2) + '\n').encode()
    parent_file.write_bytes(content)
    manifest['variant'] = UI66_PATCH_ID
    manifest['files']['UI_PATCH.json'] = hashlib.sha256(content).hexdigest()
    manifest_file.write_text(json.dumps(manifest, indent=2) + '\n')
    for name, expected in manifest['files'].items():
        path = destination / name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Derived UI66 source integrity failure: ' + name)


