def apply_experience_ui67(destination: Path) -> None:
    """Apply the verified UI67 experience layer to the exact cumulative UI66 runtime."""
    manifest_file = destination / 'RELEASE_FILES.json'
    manifest = json.loads(manifest_file.read_text())
    parent_file = destination / 'UI_PATCH.json'
    if (manifest.get('format') != 'aj-release-files-1' or manifest.get('version') != '1.34.19'
            or manifest.get('variant') != UI66_PATCH_ID):
        raise ValueError('Workspace UI67 requires the exact cumulative UI66 runtime.')
    if not parent_file.is_file() or hashlib.sha256(parent_file.read_bytes()).hexdigest() != '2435b043f0a5d06e433a41356cb373eb79081b638c2e615ebd45b0815898c995':
        raise ValueError('Workspace UI67 parent provenance mismatch.')
    parent = json.loads(parent_file.read_text())
    if parent.get('format') != 'wavelink-source-overlay-1' or parent.get('patch_id') != UI66_PATCH_ID:
        raise ValueError('Workspace UI67 requires the reviewed UI66 parent overlay.')
    prepared = {}
    for name, record in _UI67_FILES.items():
        path = destination / name
        expected = record['before_sha256']
        if expected is None:
            if path.exists() or path.is_symlink() or name in manifest['files']:
                raise ValueError('New UI67 resource unexpectedly exists: ' + name)
        elif manifest['files'].get(name) != expected or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Workspace UI67 base-file mismatch: ' + name)
        decompressor = zlib.decompressobj()
        content = decompressor.decompress(base64.b64decode(record['zlib_base64'], validate=True), record['bytes'] + 1)
        if (not decompressor.eof or decompressor.unused_data or len(content) != record['bytes']
                or hashlib.sha256(content).hexdigest() != record['after_sha256']):
            raise ValueError('Workspace UI67 payload integrity failure: ' + name)
        prepared[name] = content
    for name, content in prepared.items():
        path = destination / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(content)
        manifest['files'][name] = _UI67_FILES[name]['after_sha256']
    inherited = list(parent.get('includes') or [])
    if UI66_PATCH_ID not in inherited:
        inherited.append(UI66_PATCH_ID)
    provenance = {
        'format': 'wavelink-source-overlay-1',
        'patch_id': UI67_PATCH_ID,
        'parent_patch_id': UI66_PATCH_ID,
        'parent_overlay_sha256': '2435b043f0a5d06e433a41356cb373eb79081b638c2e615ebd45b0815898c995',
        'upstream_version': '1.34.19',
        'upstream_archive_sha256': SOURCE_SHA256,
        'includes': inherited,
        'scope': 'Shared Wavelink experience shell with first-class My profile and Team navigation, a compact account menu, a dedicated Account & access destination, a persistent selected badge, thirty user-supplied badge-art assets, and responsive desktop/mobile presentation.',
        'data_changes': 'No database, authority, permission, API or operational-record schema change. UI67 reads existing UI66 company profiles and recognition progress and preserves the existing profile-edit route. Existing UI66 membership, recognition, operational data and device-local work remain unchanged.',
        'source_parent_extractor_sha256': '2c9e15d2e653d736bbab91155074f3e5f5846664954a4d7c0bebddb87a783977',
        'source_parent_variant': UI66_PATCH_ID,
        'badge_art': 'Thirty production WebP assets derived from the user-supplied Wavelink badge exploration artwork; stable tier-family IDs and inline fallback remain.',
        'mail_startup_m01': 'Preserved by the unchanged deploy/company_entrypoint.py repository launcher; not embedded in the runtime overlay.',
        'changed_files': {name: {key: val for key, val in record.items() if key != 'zlib_base64'} for name, record in _UI67_FILES.items()},
    }
    content = (json.dumps(provenance, indent=2) + '\n').encode()
    parent_file.write_bytes(content)
    manifest['variant'] = UI67_PATCH_ID
    manifest['files']['UI_PATCH.json'] = hashlib.sha256(content).hexdigest()
    manifest_file.write_text(json.dumps(manifest, indent=2) + '\n')
    for name, expected in manifest['files'].items():
        path = destination / name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != expected:
            raise ValueError('Derived UI67 source integrity failure: ' + name)


